package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;

public class JsonWriter_value_TriageGen2Test {

    private JsonWriter writer;
    private StringWriter stringWriter;

    @Before
    public void setUp() {
        stringWriter = new StringWriter();
        writer = new JsonWriter(stringWriter);
    }

    @Test
    public void testValue_FiniteDouble() throws IOException {
        writer.value(123.45);
        assertEquals("123.45", stringWriter.toString());
    }

    @Test
    public void testValue_ZeroValue() throws IOException {
        writer.value(0.0);
        assertEquals("0.0", stringWriter.toString());
    }

    @Test
    public void testValue_NegativeDouble() throws IOException {
        writer.value(-123.45);
        assertEquals("-123.45", stringWriter.toString());
    }

    @Test
    public void testValue_NaNDouble() {
        assertThrows(IllegalArgumentException.class, () -> {
            writer.value(Double.NaN);
        });
    }

    @Test
    public void testValue_PositiveInfinity() {
        assertThrows(IllegalArgumentException.class, () -> {
            writer.value(Double.POSITIVE_INFINITY);
        });
    }

    @Test
    public void testValue_NegativeInfinity() {
        assertThrows(IllegalArgumentException.class, () -> {
            writer.value(Double.NEGATIVE_INFINITY);
        });
    }
}
